<?php
namespace Tests;
use App\Services\{SalonStore,Tenant,PlatformGuests,Blacklist};
use Illuminate\Support\Facades\{Artisan,DB,Hash,Http};
class PlatformGuestsTest extends \Illuminate\Foundation\Testing\TestCase
{
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();Artisan::call('migrate',['--force'=>true]);Http::preventStrayRequests();$s=SalonStore::initial();$s['subscription']=['status'=>'active','plan'=>'pro'];$s['clients']=[['id'=>'linked','name'=>'Old','email'=>'own@example.com','phone'=>'06305550101','guestId'=>10],['id'=>'local','name'=>'Local','email'=>'local@example.com','phone'=>'06305550102','guestId'=>null]];$s['bookings']=[['id'=>'booking','clientId'=>'local','name'=>'Local','email'=>'local@example.com','phone'=>'06305550102','start'=>'2035-03-12T09:00:00Z','end'=>'2035-03-12T10:00:00Z','staff'=>'anna','services'=>['cut'],'serviceSnapshot'=>[['id'=>'cut','name'=>'Hajvágás','price'=>10000,'duration'=>60]],'duration'=>60,'status'=>'confirmed','attendance'=>'unmarked','token'=>str_repeat('a',48),'createdAt'=>'2026-01-01T00:00:00Z']];$s['payments']=[];DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode($s)]);$s['settings']['name']='Második Szalon';$s['clients']=[$s['clients'][0]];$s['bookings']=[];DB::table('salon_state')->insert(['id'=>2,'data'=>json_encode($s)]);DB::table('providers')->insert(['id'=>2,'name'=>'Második Szalon','email'=>'provider@example.com','password_hash'=>Hash::make('test-password-123'),'trial_started_at'=>now(),'trial_ends_at'=>now()->addMonths(2),'created_at'=>now(),'updated_at'=>now()]);DB::table('guest_accounts')->insert(['id'=>10,'name'=>'Own','profile_name'=>'Own','email'=>'login@example.com','contact_email'=>'own@example.com','phone'=>'06305550101','provider'=>'google','subject'=>'10','created_at'=>now(),'updated_at'=>now()]);$this->withSession(['platform_admin'=>true]);}
 private function client():array{return $this->getJson('/api/platform/guests/client/1/local')->assertOk()->json();}
 public function test_directory_aggregates_account_links_and_paginates_local_profiles():void{
  $this->getJson('/api/platform/guests?page=1')->assertOk()->assertJsonPath('pagination.total',2)->assertJsonCount(2,'items');$this->getJson('/api/platform/guests?kind=account&providerId=2')->assertJsonPath('items.0.id',10)->assertJsonCount(2,'items.0.providers');$this->getJson('/api/platform/guests?q=local')->assertJsonPath('pagination.total',1);$this->getJson('/api/platform/guests?q=%2B36%2030%20555-0102')->assertJsonPath('pagination.total',1);$this->getJson('/api/platform/guests?providerId=999')->assertJsonPath('pagination.total',0);
  app(SalonStore::class)->mutate(function(&$s){for($i=1;$i<=45;$i++)$s['clients'][]=['id'=>'many'.$i,'name'=>'Person '.$i,'email'=>'','phone'=>''];},false);$this->getJson('/api/platform/guests?page=2&perPage=999')->assertJsonCount(20,'items')->assertJsonPath('pagination.perPage',20);
 }
 public function test_root_only_and_no_sensitive_auth_or_booking_tokens_are_returned():void{
  $data=$this->getJson('/api/platform/guests/account/10')->assertOk()->json();$this->assertArrayNotHasKey('subject',$data['account']);$this->getJson('/api/platform/guests/client/1/local?history=bookings&page=1')->assertOk()->assertJsonMissingPath('items.0.token');$this->withSession(['platform_admin'=>false,'admin'=>true,'provider_id'=>1]);$this->getJson('/api/platform/guests')->assertForbidden();$this->patchJson('/api/platform/guests/client/2/linked',[])->assertForbidden();
 }
 public function test_local_edit_normalizes_and_refuses_conflicts_and_stale_versions():void{
  $detail=$this->client();$values=['version'=>$detail['version'],'name'=>'Renamed','phone'=>'+36 30 555-0102','email'=>'new@example.com','notes'=>'Note'];$this->patchJson('/api/platform/guests/client/1/local',$values)->assertOk();$this->assertSame('06305550102',$this->client()['client']['phone']);$this->patchJson('/api/platform/guests/client/1/local',$values)->assertStatus(409);$detail=$this->client();$this->patchJson('/api/platform/guests/client/1/local',array_replace($values,['version'=>$detail['version'],'email'=>'own@example.com']))->assertUnprocessable();$this->assertDatabaseHas('security_audit_events',['event'=>'guest_edit','subject_id'=>'local','provider_id'=>1]);
 }
 public function test_linked_contact_changes_use_account_and_propagate_without_changing_login_email():void{
  $detail=$this->getJson('/api/platform/guests/client/1/linked')->json();$this->patchJson('/api/platform/guests/client/1/linked',['version'=>$detail['version'],'name'=>'Wrong','phone'=>'06305550101','email'=>'changed@example.com'])->assertUnprocessable();$account=$this->getJson('/api/platform/guests/account/10')->json();$this->patchJson('/api/platform/guests/account/10',['version'=>$account['version'],'name'=>'New own','phone'=>'06305550103','email'=>'new-own@example.com'])->assertOk();$this->getJson('/api/platform/guests/client/2/linked')->assertJsonPath('client.name','New own')->assertJsonPath('client.email','new-own@example.com');$this->assertDatabaseHas('guest_accounts',['id'=>10,'email'=>'login@example.com','contact_email'=>'new-own@example.com']);
 }
 public function test_blacklist_is_tenant_scoped_and_deletion_keeps_booking_history():void{
  $detail=$this->client();$this->patchJson('/api/platform/guests/client/1/local/blacklist',['version'=>$detail['version'],'blocked'=>true,'reason'=>'Example'])->assertOk();$s=app(SalonStore::class)->read();$this->assertTrue(Blacklist::blocked($s,['email'=>'local@example.com']));$this->assertFalse(app(Tenant::class)->run(2,fn()=>Blacklist::blocked(app(SalonStore::class)->read(),['email'=>'local@example.com'])));$detail=$this->client();$this->deleteJson('/api/platform/guests/client/1/local',['version'=>$detail['version'],'confirmed'=>true])->assertOk();$s=app(SalonStore::class)->read();$this->assertCount(1,$s['bookings']);$this->assertSame('booking',$s['bookings'][0]['id']);$this->getJson('/api/platform/guests?visibility=deleted')->assertJsonPath('pagination.total',1);$this->assertDatabaseHas('security_audit_events',['event'=>'guest_blacklist']);
 }
 public function test_account_deletion_detaches_but_preserves_service_profiles_and_revokes_passwords():void{
  DB::table('guest_credentials')->insert(['guest_id'=>10,'email'=>'login@example.com','password_hash'=>'not-returned','created_at'=>now(),'updated_at'=>now()]);$account=$this->getJson('/api/platform/guests/account/10')->json();$this->deleteJson('/api/platform/guests/account/10',['version'=>$account['version'],'confirmed'=>true])->assertOk();$this->assertDatabaseMissing('guest_accounts',['id'=>10]);$this->assertDatabaseMissing('guest_credentials',['guest_id'=>10]);$this->getJson('/api/platform/guests/client/1/linked')->assertOk()->assertJsonPath('client.guestId',null)->assertJsonPath('client.email','own@example.com');$this->assertDatabaseHas('security_audit_events',['event'=>'guest_delete','subject_type'=>'guest']);$this->withSession(['guest_id'=>10,'admin'=>false]);$this->getJson('/api/guest')->assertUnauthorized()->assertSessionMissing('guest_id');
 }
 public function test_support_login_is_explicit_audited_scoped_and_restores_original_auth():void{
  $this->withSession(['platform_admin'=>true,'admin'=>true,'provider_id'=>1,'guest_id'=>10]);$this->postJson('/api/platform/support',['providerId'=>2])->assertUnprocessable();$this->postJson('/api/platform/support',['providerId'=>2,'confirmed'=>true])->assertOk()->assertJsonPath('url','/munkaterulet/naptar?provider=2')->assertSessionHas('provider_id',2)->assertSessionHas('admin',true)->assertSessionHas('platform_admin',true);$this->getJson('/api/platform/support')->assertJsonMissingPath('active.returnAuth');$this->getJson('/api/state?provider=2')->assertOk()->assertJsonPath('_support.providerId',2);$this->getJson('/api/state?provider=1')->assertForbidden();$this->patchJson('/api/clients/linked?provider=2',['name'=>'Own','email'=>'own@example.com','phone'=>'06305550101'])->assertOk();$this->assertDatabaseHas('security_audit_events',['event'=>'support_write','provider_id'=>2,'subject_id'=>'PATCH api/clients']);$this->getJson('/api/csrf')->assertOk();DB::table('providers')->where('id',2)->update(['active'=>false]);$this->getJson('/api/csrf')->assertOk();$this->postJson('/api/platform/support/stop?provider=2')->assertOk()->assertSessionHas('provider_id',1)->assertSessionHas('guest_id',10)->assertSessionMissing('platform_support');$this->assertDatabaseHas('security_audit_events',['event'=>'support_start','provider_id'=>2]);$this->assertDatabaseHas('security_audit_events',['event'=>'support_end','provider_id'=>2]);$this->getJson('/api/platform/security-audit?providerId=2')->assertOk()->assertJsonPath('items.0.provider_name','Második Szalon');$this->withSession(['platform_admin'=>false]);$this->postJson('/api/platform/support',['providerId'=>2,'confirmed'=>true])->assertForbidden();
 }
 public function test_successful_platform_login_is_logged_with_no_password():void{
  config(['operator.password_hash'=>Hash::make('root-test-password')]);$this->withSession(['platform_admin'=>false]);$this->postJson('/api/platform/login',['password'=>'root-test-password'])->assertOk();$this->assertDatabaseHas('security_audit_events',['event'=>'login','actor_type'=>'platform']);$this->getJson('/api/platform/security-audit?page=1')->assertOk()->assertJsonMissingPath('items.0.password')->assertJsonPath('pagination.perPage',30);
 }
 public function test_account_contact_conflict_rolls_back_for_every_provider():void{
  $a=$this->getJson('/api/platform/guests/account/10')->json();$this->patchJson('/api/platform/guests/account/10',['version'=>$a['version'],'name'=>'Wrong update','phone'=>'06305550103','email'=>'local@example.com'])->assertUnprocessable();$this->assertDatabaseHas('guest_accounts',['id'=>10,'contact_email'=>'own@example.com','profile_name'=>'Own']);$this->getJson('/api/platform/guests/client/2/linked')->assertJsonPath('client.email','own@example.com');
 }
 public function test_guest_booking_history_is_paged_and_preserves_read_only_projection():void{
  $state=json_decode(DB::table('salon_state')->where('id',1)->value('data'),true);$base=$state['bookings'][0];for($i=1;$i<=60;$i++)$state['bookings'][]=array_replace($base,['id'=>'extra'.$i,'start'=>now()->addDays($i)->toISOString()]);DB::table('salon_state')->where('id',1)->update(['data'=>json_encode($state)]);$this->getJson('/api/platform/guests/client/1/local?history=bookings&page=2&perPage=999')->assertOk()->assertJsonCount(20,'items')->assertJsonPath('pagination.total',61)->assertJsonMissingPath('items.0.token');$this->getJson('/api/platform/guests/client/1/local?history=bookings&page=999')->assertJsonCount(1,'items')->assertJsonPath('pagination.page',4);
 }

}
